from taf.ul.trs_e2e_fw.lib.ems.nom.nom_base import NomBase
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable

logger = BackgroundLogger.Instance()


class WorkflowEngine(NomBase):

    def __init__(self):
        super(WorkflowEngine, self).__init__()

    def apply_site_template(self, **kwargs):
        """
        Apply the assigned site templates to the SBTS plan

        | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
        | apply_templates | Mandatory | (List[str]) - List of integrated element ids |  |
        | plan_name | Mandatory | (bool) - If set to true, complement plan operation will be performed. |  |
        | validate | Mandatory | (bool) - If set to true, offline plan validation will be performed. |  |
        | timeout | 10 | (int) - Time to wait for the response of the current operation |  |
        | run_async | False | (bool) - If set to True keyword will not wait for operation result and |  |
        |  |  |  return dict object that contains operation_id key instead. |  |
        |  |  | Refer below for more details. |  |
        | private_key | "" | (str) - This is a private key in PEM format. Refer below for more details. |  |
        | user_defined_name | "" | (str) - User can provide own name for this operation execution. |  |
        | user_defined_description | "" | (str) - User can provide with own description about this operation execution. |  |
        | deploy_cnf | True | (bool) - If set to True, deploy-planned-cnfs operation will be performed. |  |

        *NOM Parameters Info:*\n
        _private_key_ : This is a private key in PEM format. If provided, the operation will use it to decrypt all OAM
        link password attributes stored as parameters in the planned managed objects. If provided, the operation expects all such
        attributes to be encrypted with the RSA algorithm base64 form. All the new line characters in .pem content should be converted to
        and then concatenate all the PEM lines as one long string. The following command can be used for the conversion:
        awk 'NF {sub(/
        /, ""); printf "%s ",$0;}' pem-certificate-name.pem
        If provided with empty value, the operation will fail. If not provided, the operation expects all such parameters to be in plain text form.

        _run_async:_\n	If set to True keyword will not wait for operation result and return dict object that contains operation_id key instead.
        Optional parameters: :param bool overwrite: Users can optionally specify if already activated configuration should be overwritten.
        If not provided, the operation will fail for already activated configurations.

        *Returns:*
        _NOM:_ every dict contains operation_id, status and timestamp keys
        _Others:_ None

        @raise
            From SSH library : SSHException
        """
        nom_plan = kwargs.get("plan_name", "iv_fw_plan")
        nom_plan_template = get_config_variable(['nom_plan_template', nom_plan])
        if not nom_plan_template['apply_templates'] or not nom_plan_template['run_async']:
            raise Exception("One or more of the mandatory parameters missing: Please provide both apply_templates and run_async.")
        nom_plan_template["nom_plan"] = nom_plan

        self.nom_factory.nom.activate_autoconfiguration(**nom_plan_template)

    def integrate_ne(self, **kwargs):
        """
        Integrate network elements defined in a given plan.

        This operation will process all managed objects in the plan and trigger NE-NOM integration sequences for all of
        them in parallel. Supported are only managed object classes from com.nokia.nms.integration adaptation. All other
        objects will be ignored.
        :param str plan_name: Name of the plan whose managed objects are to be integrated by this execution.
        :param bool reintegrate: If set to true, Reintegrate in case the NE is already integrated to NOM.
        :param int timeout: Time to wait for the response of the current operation

        :return: list(dict)
        :rtype: list
        """
        plan_name = kwargs["plan_name"]
        timeout = kwargs.get("timeout", 10)
        reintegrate = kwargs.get("reintegrate", False)
        self.nom_factory.nom.integrate_ne(plan_name, timeout=timeout, reintegrate=reintegrate)
        